$root=Resolve-Path (Join-Path $PSScriptRoot '../..');$pids=Join-Path $root '.runtime/pids';$ok=$true;$envFile=Join-Path $root '.env.native';if(Test-Path $envFile){Get-Content $envFile|Where-Object{$_ -match '^\s*[^#][^=]*='}|ForEach-Object{$key,$value=$_.Split('=',2);[Environment]::SetEnvironmentVariable($key.Trim(),$value.Trim(),'Process')}}
foreach($name in @('supervisor','api','lobby','games')){$file=Join-Path $pids "$name.pid";$processId=if(Test-Path $file){[int](Get-Content $file)}else{0};$proc=if($processId){Get-Process -Id $processId -ErrorAction SilentlyContinue}else{$null};if(-not $proc){$ok=$false};[pscustomobject]@{Service=$name;PID=$processId;Running=[bool]$proc}}
try{$health=Invoke-RestMethod "http://127.0.0.1:$($env:PORT)/health" -TimeoutSec 2;Write-Host "API health: $($health.ok), database: $($health.database)"}catch{$ok=$false;Write-Host 'API health: unavailable'}
try{$ready=Invoke-RestMethod "http://127.0.0.1:$($env:CONTROL_PORT)/ready" -TimeoutSec 2;Write-Host "Runtime ready: $($ready.ok), children: $($ready.children), uptime: $($ready.uptimeSeconds)s"}catch{$ok=$false;Write-Host 'Runtime readiness: unavailable'};if(-not $ok){exit 1}
